import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,)):
    """Call fn(); on failure wait base * 2**n seconds (jittered, capped) and retry."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** n)))
```

